import { useState } from 'react'

/**
 * The no-WebGL / reduced-motion hero art. A still frame of the same wizard, so the
 * fallback reads as a deliberate composition rather than an empty right column.
 * Generated by `npm run shoot:hero` in Task 7.
 *
 * Points at the `.png`, not `.webp`: `cwebp` isn't installed on this machine, so
 * `shoot:hero` fell back to keeping the PNG (see its script in package.json) — a
 * working fallback in the wrong format beats a missing one. Swap this back to
 * `.webp` if `cwebp` becomes available and the script is re-run.
 *
 * If the file is ever missing, we degrade honestly: hide the <img> entirely rather
 * than showing a broken-image icon with alt text describing art that isn't there.
 */
export function StaticHeroArt() {
  const [broken, setBroken] = useState(false)

  return (
    <div className="stage stage--static" aria-hidden="false">
      {!broken && (
        <img
          src="/shots/hero-wizard.png"
          alt="Illustration of a robed wizard holding a lit wand"
          onError={() => setBroken(true)}
        />
      )}
    </div>
  )
}
